import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.Bbwa0s72.js";const h=JSON.parse('{"title":"Form Proposal: EdgeWorker","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge-worker.md","filePath":"proposals/edge-worker.md"}'),o={name:"proposals/edge-worker.md"};function n(s,e,d,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="form-proposal-edgeworker" tabindex="-1">Form Proposal: EdgeWorker <a class="header-anchor" href="#form-proposal-edgeworker" aria-label="Permalink to &quot;Form Proposal: EdgeWorker&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need" tabindex="-1">Need <a class="header-anchor" href="#need" aria-label="Permalink to &quot;Need&quot;">​</a></h2><p>The v1alpha2 reset evaluated immutable edge applications on one host. That historical evaluation is not a current host or first-host claim. The portable contract describes the application a consumer wants without exposing Cloudflare, placement, routing, credentials, billing, or a host&#39;s runtime manager.</p><h2 id="portable-boundary" tabindex="-1">Portable boundary <a class="header-anchor" href="#portable-boundary" aria-label="Permalink to &quot;Portable boundary&quot;">​</a></h2><p>The candidate boundary is an immutable artifact, an entrypoint, an open runtime capability requirement, non-secret configuration, declared Resource connections, and an <code>http.request@1</code> Interface. Runtime implementation, routing, scaling, placement, assets policy, request limits, secrets, and price remain host decisions. Every field from the Legacy EdgeWorker must be justified again; the v1alpha1 document is prior art, not a starting schema.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>The artifact and entrypoint can run in a Workers-style isolate, another edge isolate, a WASI host, or a regional event runtime. <code>runtime</code> is an open capability requirement whose support is host-declared. Concurrency, timeout, asset fallback, route, compatibility date, account, and placement fields are excluded because they operate a substrate rather than identify the workload.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Artifact changes create reviewed revisions. Runtime-local state is not durable portable state. Delete retires serving identity while preserving audit and recovery evidence. Import requires exact artifact and host identity. Artifact bytes are digest-bound; credentials and secrets never enter desired/provider state; network policy remains host-owned.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI Application/Component/Link/Action, CIMI System/Machine lifecycle, TOSCA nodes/artifacts/relationships, Kubernetes Deployment and Knative Service, Crossplane reconciliation, and Terraform/OpenTofu edge providers are all applicable. The remaining gap is a deliberately small immutable edge application contract with host-owned runtime, routing, credentials, and placement.</p><h2 id="experimental-exit-evidence" tabindex="-1">Experimental exit evidence <a class="header-anchor" href="#experimental-exit-evidence" aria-label="Permalink to &quot;Experimental exit evidence&quot;">​</a></h2><p>An independent adopter (which may include Takosumi) supplies one workload evidence source only; it does not decide maturity. Canonical definition, positive/negative fixtures, compatibility and migration analysis, security review, provider-v2 behavior, package signature, and public readback remain required before <code>EdgeWorker@0.1.0</code> exists.</p>',14)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
